import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const y=JSON.parse('{"title":"SoftForge Official Tech Stack","description":"","frontmatter":{},"headers":[],"relativePath":"en/06-tech-stack.md","filePath":"en/06-tech-stack.md"}'),l={name:"en/06-tech-stack.md"};function o(i,t,d,r,c,p){return a(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="softforge-official-tech-stack" tabindex="-1">SoftForge Official Tech Stack <a class="header-anchor" href="#softforge-official-tech-stack" aria-label="Permalink to &quot;SoftForge Official Tech Stack&quot;">​</a></h1><blockquote><p><strong>The modern, contract-driven foundation engineered for AI Agents and human developers.</strong></p></blockquote><hr><h2 id="_1-stack-architecture-overview" tabindex="-1">1. Stack Architecture Overview <a class="header-anchor" href="#_1-stack-architecture-overview" aria-label="Permalink to &quot;1. Stack Architecture Overview&quot;">​</a></h2><p>SoftForge was built on a single architectural principle: <strong>every technology must be strictly typed, deterministic, and maintain an optimal context window footprint for autonomous AI Agents (LLMs).</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        FRONTEND (apps/web)                             │</span></span>
<span class="line"><span>│      React + TypeScript + Vite + Tailwind CSS + shadcn/ui             │</span></span>
<span class="line"><span>│      TanStack Query (React Query v5) + Lucide Icons                    │</span></span>
<span class="line"><span>└───────────────────────────────────▲────────────────────────────────────┘</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                       OpenAPI 3.1 Contract &amp; DTOs</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>┌───────────────────────────────────▼────────────────────────────────────┐</span></span>
<span class="line"><span>│                         BACKEND (apps/api)                             │</span></span>
<span class="line"><span>│     Python 3.12+ + FastAPI + Pydantic v2 + SQLAlchemy 2.0 Async        │</span></span>
<span class="line"><span>│     Loguru (Structured Logs) + JWT/HttpOnly Cookies + Ruff Linter      │</span></span>
<span class="line"><span>└───────────────────▲────────────────────────────────▲───────────────────┘</span></span>
<span class="line"><span>                    │                                │</span></span>
<span class="line"><span>      (Test Environment / CI)              (Production / Docker)</span></span>
<span class="line"><span>                    │                                │</span></span>
<span class="line"><span>┌───────────────────▼──────────────┐ ┌───────────────▼───────────────────┐</span></span>
<span class="line"><span>│     SQLite In-Memory             │ │      PostgreSQL 16+               │</span></span>
<span class="line"><span>│     (Executes in ~2 seconds)     │ │      (ACID &amp; High Concurrency)    │</span></span>
<span class="line"><span>└──────────────────────────────────┘ └───────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_2-backend-core-apps-api" tabindex="-1">2. Backend Core (<code>apps/api</code>) <a class="header-anchor" href="#_2-backend-core-apps-api" aria-label="Permalink to &quot;2. Backend Core (\`apps/api\`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Technology</th><th style="text-align:left;">Version</th><th style="text-align:left;">Role in SoftForge</th><th style="text-align:left;">Rationale &amp; Trade-offs</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Python</strong></td><td style="text-align:left;"><code>3.12+</code></td><td style="text-align:left;">Core API Runtime</td><td style="text-align:left;">Modern typing syntax, high readability for LLMs, extensive ecosystem.</td></tr><tr><td style="text-align:left;"><strong>FastAPI</strong></td><td style="text-align:left;"><code>0.115+</code></td><td style="text-align:left;">HTTP Framework &amp; Routing</td><td style="text-align:left;">Native OpenAPI 3.1 spec generation, built-in dependency injection, and asynchronous throughput.</td></tr><tr><td style="text-align:left;"><strong>Pydantic</strong></td><td style="text-align:left;"><code>v2.10+</code></td><td style="text-align:left;">Validation &amp; DTOs</td><td style="text-align:left;">Rust core (blazing fast), strict data validation, and clean two-way serialization.</td></tr><tr><td style="text-align:left;"><strong>SQLAlchemy</strong></td><td style="text-align:left;"><code>2.0+ (Async)</code></td><td style="text-align:left;">ORM &amp; Query Builder</td><td style="text-align:left;">Industry standard; strictly typed models with <code>Mapped[...]</code> and native <code>AsyncSession</code>.</td></tr><tr><td style="text-align:left;"><strong>Alembic</strong></td><td style="text-align:left;"><code>1.13+ (Async)</code></td><td style="text-align:left;">Database Migrations</td><td style="text-align:left;">Deterministic schema versioning with async migrations for PostgreSQL and naming conventions.</td></tr><tr><td style="text-align:left;"><strong>Loguru</strong></td><td style="text-align:left;"><code>0.7+</code></td><td style="text-align:left;">Observability &amp; Logging</td><td style="text-align:left;">Structured JSON or colorized console logs with automated <code>X-Request-ID</code> correlation.</td></tr><tr><td style="text-align:left;"><strong>PyJWT &amp; Passlib</strong></td><td style="text-align:left;">Latest</td><td style="text-align:left;">Security &amp; Authentication</td><td style="text-align:left;">Password hashing (Argon2 / bcrypt) and dual JWT support (HttpOnly cookies + Bearer headers).</td></tr><tr><td style="text-align:left;"><strong>Ruff</strong></td><td style="text-align:left;"><code>0.9+</code></td><td style="text-align:left;">Linter &amp; Formatter</td><td style="text-align:left;">Rust-based (&lt;100ms execution) replacing Black, Flake8, and isort for spotless code hygiene.</td></tr><tr><td style="text-align:left;"><strong>Pytest &amp; pytest-asyncio</strong></td><td style="text-align:left;"><code>8.0+</code></td><td style="text-align:left;">Test Suite</td><td style="text-align:left;">Async isolated execution with fixtures for database sessions and HTTP client (<code>httpx</code>).</td></tr></tbody></table><hr><h2 id="_3-frontend-core-apps-web" tabindex="-1">3. Frontend Core (<code>apps/web</code>) <a class="header-anchor" href="#_3-frontend-core-apps-web" aria-label="Permalink to &quot;3. Frontend Core (\`apps/web\`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Technology</th><th style="text-align:left;">Version</th><th style="text-align:left;">Role in SoftForge</th><th style="text-align:left;">Rationale &amp; Trade-offs</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>React</strong></td><td style="text-align:left;"><code>18+ / 19</code></td><td style="text-align:left;">UI Library</td><td style="text-align:left;">Universal SPA standard; wide component ecosystem and predictable agent editing.</td></tr><tr><td style="text-align:left;"><strong>TypeScript</strong></td><td style="text-align:left;"><code>5.0+</code></td><td style="text-align:left;">Static Typing</td><td style="text-align:left;">Guarantees that OpenAPI DTOs are strictly honored during development and compile-time.</td></tr><tr><td style="text-align:left;"><strong>Vite</strong></td><td style="text-align:left;"><code>6.0+</code></td><td style="text-align:left;">Bundler &amp; Dev Server</td><td style="text-align:left;">Instant Hot Module Replacement (HMR) powered by esbuild and Rollup.</td></tr><tr><td style="text-align:left;"><strong>Tailwind CSS</strong></td><td style="text-align:left;"><code>3.4+</code></td><td style="text-align:left;">Utility CSS</td><td style="text-align:left;">Design system consistency, zero CSS file overhead, and collision-free styling.</td></tr><tr><td style="text-align:left;"><strong>shadcn/ui &amp; Radix</strong></td><td style="text-align:left;">Standard</td><td style="text-align:left;">Component Library</td><td style="text-align:left;">Accessible (WAI-ARIA compliant), unstyled primitives with code living directly inside repo.</td></tr><tr><td style="text-align:left;"><strong>TanStack Query</strong></td><td style="text-align:left;"><code>v5</code></td><td style="text-align:left;">Server State Management</td><td style="text-align:left;">Invalidation, caching, optimistic updates, and background re-fetching.</td></tr><tr><td style="text-align:left;"><strong>Lucide Icons</strong></td><td style="text-align:left;">Latest</td><td style="text-align:left;">Icon Set</td><td style="text-align:left;">Lightweight, tree-shakeable SVG icons.</td></tr></tbody></table><hr><h2 id="_4-ai-agent-tooling-tools-scripts" tabindex="-1">4. AI Agent Tooling (<code>tools/scripts/</code>) <a class="header-anchor" href="#_4-ai-agent-tooling-tools-scripts" aria-label="Permalink to &quot;4. AI Agent Tooling (\`tools/scripts/\`)&quot;">​</a></h2><ol><li><strong><code>tools/scripts/slice_scaffold.py</code>:</strong> Deterministically creates full vertical slices (<code>schemas.py</code>, <code>models.py</code>, <code>service.py</code>, <code>router.py</code>, <code>tests/</code>).</li><li><strong><code>tools/scripts/export_openapi.py</code>:</strong> Generates OpenAPI 3.1 schema definitions.</li><li><strong><code>tools/scripts/migrate.py</code>:</strong> Unified Alembic migration runner (<code>makemigrations</code>, <code>upgrade</code>, <code>downgrade</code>, <code>sql</code>) with auto-discovery of slice models.</li><li><strong><code>tools/scripts/verify.py</code>:</strong> Quality gatekeeper running linters, migration validations, and tests before any task completion.</li></ol><hr><h2 id="_5-ci-cd-github-actions-automation" tabindex="-1">5. CI/CD &amp; GitHub Actions Automation <a class="header-anchor" href="#_5-ci-cd-github-actions-automation" aria-label="Permalink to &quot;5. CI/CD &amp; GitHub Actions Automation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Configuration</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Quality Gate Workflow</strong></td><td style="text-align:left;"><code>.github/workflows/ci.yml</code></td><td style="text-align:left;">Triggered on every <code>push</code> and <code>pull_request</code> targeting <code>main</code>. Executes <code>tools/scripts/verify.py</code> covering tests, linters, migration validations, and frontend typechecking.</td></tr><tr><td style="text-align:left;"><strong>Automated Docs Deployment</strong></td><td style="text-align:left;">Job <code>deploy-docs</code></td><td style="text-align:left;">Builds VitePress and automatically deploys the static documentation to <strong>GitHub Pages</strong> under the custom domain <code>softforge.redepronta.com</code>.</td></tr></tbody></table>`,18)])])}const f=e(l,[["render",o]]);export{y as __pageData,f as default};
